INSERT INTO "Destination" (city, country, image, description, rating, duration, price, category) VALUES
('Valletta', 'Malta', 'https://images.unsplash.com/photo-1555881400-74d7acaacd8b?w=800&q=80', 'Smallest EU capital, baroque palaces, and Blue Lagoon.', 4.8, '4-6 days', 'From $799', 'Culture'),
('Nicosia', 'Cyprus', 'https://images.unsplash.com/photo-1534430480872-3498386e7856?w=800&q=80', 'Last divided capital in Europe, Aphrodite shores and ruins.', 4.7, '5-7 days', 'From $749', 'Beach'),
('Tirana', 'Albania', 'https://images.unsplash.com/photo-1595867818082-083862f3d630?w=800&q=80', 'Colorful Blloku, Butrint UNESCO site, and Riviera beaches.', 4.6, '4-6 days', 'From $599', 'Culture'),
('Skopje', 'North Macedonia', 'https://images.unsplash.com/photo-1569591559621-921d4b7ef74b?w=800&q=80', 'Baroque statues, Ottoman bazaar, and Lake Ohrid.', 4.5, '3-5 days', 'From $579', 'Culture'),
('Podgorica', 'Montenegro', 'https://images.unsplash.com/photo-1570077188670-e3a8d69ac5ff?w=800&q=80', 'Kotor bay, Durmitor mountains, and Adriatic beaches.', 4.7, '5-7 days', 'From $699', 'Nature'),
('Pristina', 'Kosovo', 'https://images.unsplash.com/photo-1558618666-fcd25c85cd64?w=800&q=80', 'Young nation, Bill Clinton statue, and Prizren fortress.', 4.4, '3-5 days', 'From $549', 'Culture'),
('Chisinau', 'Moldova', 'https://images.unsplash.com/photo-1519197924294-4ba991a11128?w=800&q=80', 'Wine capital, Orheiul Vechi monastery, and Soviet murals.', 4.4, '3-5 days', 'From $499', 'Culture'),
('Kyiv', 'Ukraine', 'https://images.unsplash.com/photo-1560969184-10fe8719e047?w=800&q=80', 'Golden domes, Maidan square, and rich Slavic heritage.', 4.7, '5-7 days', 'From $649', 'Culture'),
('Lviv', 'Ukraine', 'https://images.unsplash.com/photo-1541849546-216549ae216d?w=800&q=80', 'Coffee culture, Habsburg architecture, and art nouveau.', 4.8, '4-6 days', 'From $599', 'Culture'),
('Tbilisi Old Town', 'Georgia', 'https://images.unsplash.com/photo-1580101741682-68faa85e8e3b?w=800&q=80', 'Sulfur baths, balconied houses, and Georgian wine.', 4.9, '5-7 days', 'From $649', 'Culture'),
('Beijing', 'China', 'https://images.unsplash.com/photo-1508804185872-d7badad00f7d?w=800&q=80', 'Great Wall, Forbidden City, and Peking duck feasts.', 4.8, '6-9 days', 'From $999', 'Culture'),
('Shanghai', 'China', 'https://images.unsplash.com/photo-1545893835-abaa8f1a3f8c?w=800&q=80', 'The Bund skyline, Yu Garden, and futuristic Pudong.', 4.8, '5-8 days', 'From $999', 'City'),
('Chengdu', 'China', 'https://images.unsplash.com/photo-1566230724840-14e0d6e7edb5?w=800&q=80', 'Giant pandas, spicy hot pot, and Sichuan opera.', 4.8, '5-7 days', 'From $899', 'Culture'),
('Hong Kong', 'China', 'https://images.unsplash.com/photo-1483683804023-6ccdb62f86ef?w=800&q=80', 'Night markets, dim sum, Victoria Peak, and trams.', 4.9, '5-7 days', 'From $999', 'City'),
('Ulaanbaatar', 'Mongolia', 'https://images.unsplash.com/photo-1557530360-f4b49aadbc39?w=800&q=80', 'Gobi desert, ger camps, and Naadam festival.', 4.7, '7-10 days', 'From $1,099', 'Adventure'),
('Pyongyang', 'North Korea', 'https://images.unsplash.com/photo-1524235975426-093c4bf9a536?w=800&q=80', 'Highly restricted but unforgettable Juche monuments.', 4.3, '5-7 days', 'From $1,499', 'Culture'),
('Addis Ababa', 'Ethiopia', 'https://images.unsplash.com/photo-1552422535-c45813c61732?w=800&q=80', 'Lalibela rock churches, coffee origin, and Rift Valley.', 4.7, '7-10 days', 'From $899', 'Culture'),
('Antananarivo', 'Madagascar', 'https://images.unsplash.com/photo-1516426122078-c23e76319801?w=800&q=80', 'Lemurs, baobab trees, and unique biodiversity.', 4.7, '10-14 days', 'From $1,399', 'Nature'),
('Maputo', 'Mozambique', 'https://images.unsplash.com/photo-1527631746610-bca00a040d60?w=800&q=80', 'Mozambique Island, dhow sailing, and coral reefs.', 4.6, '7-10 days', 'From $999', 'Beach'),
('Lusaka', 'Zambia', 'https://images.unsplash.com/photo-1549880338-65ddcdfd017b?w=800&q=80', 'Victoria Falls, Lower Zambezi, and walking safaris.', 4.8, '7-10 days', 'From $1,299', 'Nature');
